// Sinh tự động từ GamePresets.kt (Android) để 2 bản giống nhau
struct GamePreset: Identifiable { let name: String; let notes: String; var id: String { name } }

enum GamePresets {
    static let all: [GamePreset] = [
        GamePreset(name: "God of War Ragnarök", notes: "Giữ nguyên tên: Kratos, Atreus, Freya, Mimir, Thor, Odin, Brok, Sindri, Angrboda.\nKratos gọi Atreus là \"Boy\" → dịch \"nhóc\"/\"con\"; Kratos xưng \"ta\", gọi Atreus \"con\".\nAtreus gọi Kratos \"Father\" → \"Cha\", xưng \"con\".\nMimir nói kiểu dí dỏm, gọi Kratos \"brother\" → \"người anh em\".\nVăn phong thần thoại Bắc Âu, trang trọng nhưng gọn."),
        GamePreset(name: "The Last of Us Part I / II", notes: "Giữ nguyên tên: Joel, Ellie, Tommy, Tess, Abby, Dina, Jesse, Lev.\nJoel – Ellie: Joel xưng \"tôi\"/\"chú\", gọi Ellie \"nhóc\"/\"cháu\"; Ellie xưng \"cháu\"/\"tôi\" tuỳ lúc, giọng tuổi teen, hay chửi thề nhẹ.\nFireflies → \"Đom Đóm\", Infected → \"Kẻ nhiễm\", Clicker giữ nguyên.\nVăn phong đời thường, ngắn, có chất bụi bặm."),
        GamePreset(name: "Ghost of Tsushima", notes: "Giữ nguyên tên: Jin Sakai, Lord Shimura, Yuna, Taka, Khotun Khan, Ishikawa, Masako, Kenji.\nJin gọi Lord Shimura là \"Uncle\" → \"Chú\", xưng \"cháu\"; Shimura gọi Jin \"cháu\", xưng \"ta\".\nMongols → \"quân Mông Cổ\"; samurai, katana giữ nguyên; \"The Ghost\" → \"Bóng Ma\".\nVăn phong cổ trang Nhật, trang trọng."),
        GamePreset(name: "Elden Ring", notes: "Giữ nguyên tên riêng: Melina, Ranni, Radahn, Malenia, Godrick, Margit, Marika, Erdtree (Cây Erd).\nTarnished → \"Kẻ Tàn Tạ\"; Lands Between → \"Vùng Đất Giữa\"; Great Rune → \"Đại Cổ Tự\".\nNPC nói giọng cổ: xưng \"ta\", gọi người chơi \"ngươi\"."),
        GamePreset(name: "Black Myth: Wukong", notes: "Dùng tên Hán Việt quen thuộc theo Tây Du Ký: Sun Wukong → Tôn Ngộ Không, Destined One → Thiên Mệnh Nhân,\nZhu Bajie → Trư Bát Giới, Tang Sanzang → Đường Tăng, Erlang Shen → Nhị Lang Thần, Guanyin → Quan Âm, Yaoguai → Yêu quái.\nVăn phong cổ trang Trung Hoa: \"ta – ngươi\", \"lão phu\", \"tiểu tử\"."),
        GamePreset(name: "Marvel's Spider-Man 2", notes: "Giữ nguyên tên: Peter Parker, Miles Morales, Mary Jane (MJ), Harry Osborn, Kraven, Venom, Ganke, Rio.\nPeter – Miles: Peter xưng \"anh\", gọi Miles \"em\"/\"nhóc\"; Miles gọi Peter \"anh\".\nVăn phong trẻ trung, hài hước, câu đùa ngắn gọn."),
        GamePreset(name: "Red Dead Redemption 2", notes: "Giữ nguyên tên: Arthur Morgan, Dutch van der Linde, John Marston, Hosea, Sadie, Micah, Charles, Abigail.\nDutch gọi Arthur \"son\" → \"con trai\"/\"chú em\"; Arthur xưng \"tôi\".\nVăn phong miền Tây cao bồi, thô ráp, có chửi thề."),
        GamePreset(name: "The Witcher 3", notes: "Giữ nguyên tên: Geralt, Ciri, Yennefer, Triss, Dandelion, Vesemir, Eredin.\nWitcher giữ nguyên; Wild Hunt → \"Săn Hoang\"; Geralt nói cộc lốc, xưng \"tôi\"/\"ta\".\nGeralt – Ciri: Ciri gọi Geralt \"Geralt\", Geralt gọi Ciri \"con\"/\"Ciri\"."),
        GamePreset(name: "Final Fantasy VII Rebirth", notes: "Giữ nguyên tên: Cloud, Tifa, Aerith, Barret, Red XIII, Yuffie, Cait Sith, Sephiroth, Zack.\nShinra, SOLDIER, Materia giữ nguyên. Cloud nói ngắn, lạnh lùng, xưng \"tôi\".\nVăn phong anime JRPG, tự nhiên."),
        GamePreset(name: "Resident Evil 4", notes: "Giữ nguyên tên: Leon, Ashley, Luis, Ada, Krauser, Salazar, Saddler, Hunnigan.\nLeon xưng \"tôi\", gọi Ashley \"cô\"; Ashley gọi Leon \"anh\".\nLos Illuminados giữ nguyên; Ganado → \"dân làng bị nhiễm\". Văn phong kinh dị hành động, câu ngắn."),
        GamePreset(name: "Stellar Blade", notes: "Giữ nguyên tên: EVE, Adam, Lily, Raven, Kaya, Enya.\nNaytiba giữ nguyên. EVE nói ngắn, điềm tĩnh, xưng \"tôi\".\nAdam và Lily gọi EVE là \"EVE\", xưng \"tôi\" hoặc \"anh\"/\"em\" tuỳ thân mật.\nVăn phong khoa học viễn tưởng hậu tận thế."),
        GamePreset(name: "Final Fantasy XVI", notes: "Giữ nguyên tên: Clive Rosfield, Joshua, Jill Warrick, Cidolfus Telamon (Cid), Torgal, Barnabas, Benedikta.\nDominant, Eikon, Bearer, Mothercrystal giữ nguyên tiếng Anh.\nClive gọi Joshua là em trai (\"em\"), Joshua gọi Clive \"anh\".\nVăn phong trung cổ giả tưởng, trang trọng."),
        GamePreset(name: "Horizon Forbidden West", notes: "Giữ nguyên tên: Aloy, Varl, Zo, Erend, Sylens, Kotallo, Alva, Beta, Tilda.\nTên máy móc (Tallneck, Thunderjaw, Sunwing...) giữ nguyên.\nAloy xưng \"tôi\", nói thẳng thắn, quyết đoán.\nTên bộ tộc Nora, Carja, Tenakth, Utaru giữ nguyên."),
        GamePreset(name: "Uncharted 4", notes: "Giữ nguyên tên: Nathan Drake (Nate), Sam Drake, Elena Fisher, Victor Sullivan (Sully), Rafe Adler, Nadine Ross.\nSully gọi Nate là \"kid\" → \"nhóc\"; Nate gọi Sully \"ông\" hoặc \"Sully\".\nNate và Sam là anh em: Sam là anh.\nVăn phong phiêu lưu, hài hước, câu đùa nhanh."),
        GamePreset(name: "Cyberpunk 2077", notes: "Giữ nguyên tên: V, Johnny Silverhand, Jackie Welles, Judy Alvarez, Panam Palmer, Takemura, Rogue.\nNight City, Arasaka, netrunner, cyberware giữ nguyên.\n\"Choom\" → \"bồ\"; \"preem\" → \"xịn\"; \"gonk\" → \"đồ ngốc\".\nJohnny nói cộc cằn, chửi thề nhiều. Văn phong đường phố, tiếng lóng."),
        GamePreset(name: "Baldur's Gate 3", notes: "Giữ nguyên tên: Shadowheart, Astarion, Gale, Lae'zel, Karlach, Wyll, Halsin, Minthara.\nIllithid, Mind Flayer, tadpole (\"nòng nọc\") giữ đúng.\nAstarion nói mỉa mai, kiểu cách; Lae'zel lạnh lùng, gọi người khác \"istik\".\nVăn phong giả tưởng D&D."),
        GamePreset(name: "Death Stranding", notes: "Giữ nguyên tên: Sam Porter Bridges, Fragile, Die-Hardman, Higgs, Amelie, Deadman, Heartman, Mama, Lockne.\nBB (Lou), BT, Beach, chiral, Timefall giữ nguyên.\nSam nói ít, cộc lốc, xưng \"tôi\".\nVăn phong trầm, triết lý."),
        GamePreset(name: "Assassin's Creed Shadows", notes: "Giữ nguyên tên: Naoe, Yasuke, Oda Nobunaga, Akechi Mitsuhide, Tokugawa Ieyasu.\nShinobi, samurai, katana, daimyo giữ nguyên.\nVăn phong cổ trang Nhật thời Chiến Quốc: kính ngữ \"đại nhân\", \"chúa công\"."),
        GamePreset(name: "Hogwarts Legacy", notes: "Giữ nguyên tên: Professor Fig, Ranrok, Sebastian Sallow, Natsai Onai (Natty), Poppy Sweeting, Ominis Gaunt.\nTên phép thuật (Lumos, Accio, Avada Kedavra...), Hogwarts, Muggle, Gryffindor/Slytherin/Ravenclaw/Hufflepuff giữ nguyên.\nHọc sinh gọi nhau \"cậu\", xưng \"tớ\"; gọi giáo sư là \"thầy\"/\"cô\".\nVăn phong phép thuật, gần với bản dịch Harry Potter tiếng Việt."),
        GamePreset(name: "Persona 5 Royal", notes: "Giữ nguyên tên: Joker, Morgana (Mona), Ryuji (Skull), Ann (Panther), Yusuke (Fox), Makoto (Queen), Futaba (Oracle), Haru (Noir), Akechi.\nPhantom Thieves, Metaverse, Palace, Shadow, Persona giữ nguyên.\nHọc sinh xưng \"tớ\"/\"cậu\"; senpai giữ nguyên.\nRyuji nói bỗ bã; Morgana xưng \"ta\". Văn phong anime học đường."),
        GamePreset(name: "Sekiro: Shadows Die Twice", notes: "Wolf → \"Sói\" (người chơi), Kuro – Divine Heir → \"Thần Tử\", Isshin Ashina, Genichiro Ashina, Emma, Owl (\"Cú\" – cha nuôi của Sói).\nSói gọi Kuro là \"chủ nhân\", xưng \"tôi\" hoặc \"thuộc hạ\".\nVăn phong cổ trang Nhật, nhân vật lớn tuổi xưng \"ta\", gọi \"ngươi\"."),
        GamePreset(name: "Star Wars Jedi: Survivor", notes: "Giữ nguyên tên: Cal Kestis, BD-1, Cere Junda, Greez, Merrin, Bode Akuna, Dagan Gera.\nJedi, Sith, lightsaber, Empire giữ nguyên; the Force → \"Thần Lực\".\nVăn phong phiêu lưu không gian, tự nhiên."),
        GamePreset(name: "It Takes Two", notes: "Giữ nguyên tên: Cody, May, Rose, Dr. Hakim (\"Book of Love\" → \"Sách Tình Yêu\").\nCody và May là vợ chồng sắp ly hôn: gọi nhau \"anh\"/\"em\", hay cãi nhau.\nRose là con gái, gọi \"bố\"/\"mẹ\". Văn phong hài hước, gia đình."),
        GamePreset(name: "Ratchet & Clank: Rift Apart", notes: "Giữ nguyên tên: Ratchet, Clank, Rivet, Kit, Dr. Nefarious, Captain Qwark.\nRatchet và Clank là bạn thân, gọi nhau \"cậu\"/\"tớ\".\nVăn phong hoạt hình, vui nhộn, chơi chữ."),
        GamePreset(name: "Silent Hill 2", notes: "Giữ nguyên tên: James Sunderland, Mary, Maria, Angela, Eddie, Laura, Pyramid Head.\nJames xưng \"tôi\"; Laura là bé gái, nói xấc xược.\nVăn phong kinh dị tâm lý, u buồn, câu ngắn."),
        GamePreset(name: "Alan Wake 2", notes: "Giữ nguyên tên: Alan Wake, Saga Anderson, Alex Casey, Mr. Scratch, Tim Breaker.\nDark Place, Bright Falls, Cauldron Lake giữ nguyên.\nSaga và Casey là đặc vụ FBI, xưng hô công việc \"tôi\"/\"anh\"/\"cô\". Văn phong kinh dị trinh thám."),
        GamePreset(name: "Kingdom Come: Deliverance II", notes: "Giữ nguyên tên: Henry, Hans Capon, Sir Radzig Kobyla, Hanush, Mutt (chó của Henry).\nHenry gọi Hans là \"ngài\" (my lord), Hans gọi Henry \"anh\"/\"ngươi\" khi trêu.\nVăn phong trung cổ châu Âu, có chửi thề dân dã."),
        GamePreset(name: "Ghost of Yōtei", notes: "Giữ nguyên tên nhân vật và địa danh Nhật Bản (Ezo, Yōtei).\nVăn phong cổ trang Nhật, người lớn tuổi xưng \"ta\", gọi \"ngươi\"; kính ngữ \"đại nhân\"."),
        GamePreset(name: "Monster Hunter Wilds", notes: "Hunter → \"Thợ Săn\", Palico giữ nguyên, tên quái vật giữ nguyên tiếng Anh.\nVăn phong phiêu lưu, nhẹ nhàng."),
        GamePreset(name: "Dragon's Dogma 2", notes: "Arisen, Pawn giữ nguyên. Tên vương quốc Vermund, Battahl giữ nguyên.\nPawn nói lịch sự, gọi người chơi \"chủ nhân\". Văn phong trung cổ giả tưởng."),
    ]
}
